use context::Context;
use unwind::CallSiteRecord;

/// System V entry trampoline generated by kiln-cg: calls a Lisp function
/// object with `nargs` (0 or 1) arguments and returns its primary value.
/// It records its frame as the base of a segment of Lisp frames.
pub type EnterFn =
    unsafe extern "C" fn(ctx: *mut Context, fobj: u64, entry: *const u8, nargs: u64, a0: u64) -> u64;

static ENTER: std::sync::OnceLock<EnterFn> = std::sync::OnceLock::new();

pub(crate) fn enter_fn() -> EnterFn {
    *ENTER.get().expect("no module loaded")
}

/// Emitted by kiln-cg into every AOT object as `kiln_module_info`.
/// Layout is part of the ABI.
#[repr(C)]
pub struct ModuleInfo {
    pub enter: EnterFn,
    /// Init function objects (tagged), run in order.
    pub inits: *const u64,
    pub ninits: u64,
    pub callsites: *const CallSiteRecord,
    pub ncallsites: u64,
    pub stackmaps: *const gc::StackMapRecord,
    pub nstackmaps: u64,
    /// Addresses of static words that are GC roots.
    pub roots: *const usize,
    pub nroots: u64,
    /// Shared functions and data that code compiled at run time refers to
    /// by name (`EXPORTED_NAMES`).
    pub exports: *const Export,
    pub nexports: u64,
    /// Debug records of the functions (debug.rs).
    pub debug: *const debug::FuncDebugRecord,
    pub ndebug: u64,
}

/// An entry of a module's export table: a NUL-terminated name and an
/// address.
#[repr(C)]
pub struct Export {
    pub name: *const u8,
    pub addr: usize,
}

/// The shared definitions a module exports, if it defines them: code
/// compiled into the running image (`kiln_rt_jit` in kiln-cg) imports them
/// instead of defining its own, since it compares function entries with
/// the undefined-function entry.
pub const EXPORTED_NAMES: &[&str] = &[
    "kiln_undefined_function",
    "kiln_undefined_setf_function",
    "kiln_funcallable_trampoline",
    "kiln_funcallable_unset",
    "kiln_funcallable_unset_fobj",
];

static EXPORTS: std::sync::RwLock<Vec<(String, usize)>> = std::sync::RwLock::new(Vec::new());

pub fn register_export(name: &str, addr: usize) {
    let mut exports = EXPORTS.write().unwrap();
    if !exports.iter().any(|(n, _)| n == name) {
        exports.push((name.to_string(), addr));
    }
}

/// The address a loaded module exported under `name`.
pub fn exported(name: &str) -> Option<usize> {
    EXPORTS.read().unwrap().iter().find(|(n, _)| n == name).map(|&(_, a)| a)
}

/// Registers the call sites, stack maps and static roots of code loaded
/// into the running image.
/// Registers a program loaded by kiln-cg's JIT, which images cannot hold
/// (image.rs). Code compiled into the running image is registered by
/// `code::register`.
pub fn register_code(
    callsites: &[CallSiteRecord],
    maps: &[gc::StackMapRecord],
    roots: &[usize],
    debug: &[debug::FuncDebugRecord],
) {
    image::note_runtime_code();
    register_code_tables(callsites, maps, roots);
    debug::register(debug);
}

fn register_code_tables(callsites: &[CallSiteRecord], maps: &[gc::StackMapRecord], roots: &[usize]) {
    unwind::register_callsites(callsites);
    gc::register_stack_maps(maps);
    gc::register_static_roots(roots);
}

/// # Safety
/// `fobj` must be a tagged function object.
pub unsafe fn function_entry(fobj: u64) -> *const u8 {
    unsafe { (*((fobj - object::TAG_GENERAL) as *const object::FunctionObj)).entry }
}

/// Size of the stack Lisp runs on: `KILN_STACK_SIZE` bytes if set, else
/// 64 MiB. A main thread has 8 MiB, which deep recursions of the compiler
/// on kiln exceed. The pages are reserved, not committed.
fn lisp_stack_size() -> usize {
    std::env::var("KILN_STACK_SIZE")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(64 << 20)
}

/// Registers the module's call sites, stack maps and roots, then runs its
/// init functions in order, on a thread with a stack of
/// `lisp_stack_size()` bytes.
///
/// # Safety
/// `info` must describe correctly compiled and loaded code.
pub unsafe fn run_module(info: &ModuleInfo) -> i32 {
    struct Info(*const ModuleInfo);
    unsafe impl Send for Info {}
    let info = Info(info);
    std::thread::Builder::new()
        .name("lisp".into())
        .stack_size(lisp_stack_size())
        .spawn(move || {
            let info = info;
            unsafe { run_module_here(&*info.0) }
        })
        .expect("cannot start the Lisp thread")
        .join()
        .unwrap_or(1)
}

unsafe fn run_module_here(info: &ModuleInfo) -> i32 {
    object::init_statics();
    image::note_module_info(info as *const ModuleInfo as usize);
    unsafe {
        register_code_tables(
            std::slice::from_raw_parts(info.callsites, info.ncallsites as usize),
            std::slice::from_raw_parts(info.stackmaps, info.nstackmaps as usize),
            std::slice::from_raw_parts(info.roots, info.nroots as usize),
        );
        debug::register(std::slice::from_raw_parts(info.debug, info.ndebug as usize));
        image::note_executable();
        for e in std::slice::from_raw_parts(info.exports, info.nexports as usize) {
            let name = std::ffi::CStr::from_ptr(e.name as *const std::ffi::c_char);
            register_export(&name.to_string_lossy(), e.addr);
        }
        let _ = ENTER.set(info.enter);
        // Started from an image: call its toplevel function instead of
        // the init functions. Mapped before MMTk reserves its memory.
        let toplevel = match image::load() {
            Ok(t) => t,
            Err(e) => {
                eprintln!("kiln: {e}");
                return 1;
            }
        };
        let mut ctx = Context::new();
        // The Lisp thread's stack: about lisp_stack_size() bytes below this
        // frame.
        let here = &raw const ctx as usize;
        let size = lisp_stack_size();
        stack::set_stack_limits(&mut *ctx, here.saturating_sub(size) + (64 << 10), size);
        profile::start_from_env(&mut *ctx);
        debug::write_function_map();
        match toplevel {
            Some(f) => {
                (info.enter)(&mut *ctx, f, function_entry(f), 0, 0);
            }
            None => {
                for &init in std::slice::from_raw_parts(info.inits, info.ninits as usize) {
                    (info.enter)(&mut *ctx, init, function_entry(init), 0, 0);
                }
            }
        }
        profile::finish_from_env();
        use std::io::Write;
        let _ = std::io::stdout().flush();
        0
    }
}

/// Runtime symbols that JIT-compiled code may reference.
pub fn symbols() -> Vec<(&'static str, *const u8)> {
    vec![
        ("kiln_nil", &raw const object::kiln_nil as *const u8),
        ("kiln_t", &raw const object::kiln_t as *const u8),
        ("kiln_rt_print", rtfun::kiln_rt_print as *const u8),
        ("kiln_rt_error", rtfun::kiln_rt_error as *const u8),
        ("kiln_rt_identity_hash", rtfun::kiln_rt_identity_hash as *const u8),
        ("kiln_rt_fd_write", rtfun::kiln_rt_fd_write as *const u8),
        ("kiln_rt_fd_read", rtfun::kiln_rt_fd_read as *const u8),
        ("kiln_rt_float_decimal", rtfun::kiln_rt_float_decimal as *const u8),
        ("kiln_rt_sys", rtfun::kiln_rt_sys as *const u8),
        ("kiln_rt_poll", rtfun::kiln_rt_poll as *const u8),
        ("kiln_rt_alloc", gc::kiln_rt_alloc as *const u8),
        ("kiln_rt_gc", gc::kiln_rt_gc as *const u8),
        ("kiln_rt_gc_count", gc::kiln_rt_gc_count as *const u8),
        ("kiln_rt_save_image", image::kiln_rt_save_image as *const u8),
        ("kiln_rt_frame", debug::kiln_rt_frame as *const u8),
        (
            "kiln_rt_call_on_new_stack",
            stack::kiln_rt_call_on_new_stack as *const u8,
        ),
        ("kiln_rt_throw", unwind::kiln_rt_throw as *const u8),
        ("kiln_rt_integer_op", bignum::kiln_rt_integer_op as *const u8),
        ("kiln_rt_number_op", number::kiln_rt_number_op as *const u8),
        ("kiln_rt_tls_index", special::kiln_rt_tls_index as *const u8),
        ("kiln_rt_exit_to", unwind::kiln_rt_exit_to as *const u8),
        (
            "kiln_rt_continue_unwind",
            unwind::kiln_rt_continue_unwind as *const u8,
        ),
    ]
}
